// JAH demo program — Dewey tree
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
function node(n,c){return {n:n,c:c||[]};}
var dewey=node('000 Knowledge',[node('500 Science',[node('510 Math',[node('516 Geometry')])])]);
function find(t,name){if(t.n.indexOf(name)===0)return t;for(var i=0;i<t.c.length;i++){var f=find(t.c[i],name);if(f)return f;}return null;}
function depth(t,name,d){d=d||0;if(t.n.indexOf(name)===0)return d;for(var i=0;i<t.c.length;i++){var f=depth(t.c[i],name,d+1);if(f>=0)return f;}return -1;}
check("find 516", find(dewey,'516').n, "516 Geometry");
check("depth of 516 is 3", depth(dewey,'516'), 3);
check("root is 000", dewey.n, "000 Knowledge");
var __ok=true;
__checks.forEach(function(c){var ok=String(c[1])===String(c[2]);__ok=ok&&__ok;console.log((ok?"PASS":"FAIL")+" | "+c[0]+" => "+c[1]);});
console.log(__ok?"ALL CHECKS PASSED":"SOME CHECKS FAILED");
if(!__ok){throw new Error("demo self-check failed");}

